// TestSandboxExecIntegration_GitVersion verifies that /usr/bin/git --version
// exits 0 under the v3 profile (P4 in F.1 §3.1). xcrun cache-write errors
// on stderr are acceptable (non-fatal, SIP-related per F.1 §4.4).
// On hosts where /var/select/developer_dir is absent, DEVELOPER_DIR is set
// to /Library/Developer/CommandLineTools via baseEnv.
func TestSandboxExecIntegration_GitVersion(t *testing.T) {
	if !sandboxExecAvailable() {
		t.Skip("sandbox-exec not available")
	}
	if _, err := os.Stat("/usr/bin/git"); err != nil {
		t.Skip("/usr/bin/git not present")
	}
	m, stagingHome := newIntegrationManager(t)
	profilePath := writeProfileForIntegration(t, m)

	out, code := runUnderSandbox(t, profilePath, baseEnv(stagingHome), "/usr/bin/git", "--version")
	if code != 0 {
		t.Errorf("/usr/bin/git --version: want exit 0, got %d\noutput: %s", code, out)
	}
	if !strings.Contains(out, "git version") {
		t.Errorf("/usr/bin/git --version: expected 'git version' in output; got: %q", out)
	}
}

