// TestSandboxExecIntegration_OpencodeNoSIGABRT verifies that the opencode
// harness exits without SIGABRT under the v3 profile (P8 in F.1 §3.1).
// Exit 0 or any non-SIGABRT exit code is acceptable — "unexpected error"
// from a missing server is fine. SIGABRT (exit code 134 on Darwin) is not.
func TestSandboxExecIntegration_OpencodeNoSIGABRT(t *testing.T) {
	if !sandboxExecAvailable() {
		t.Skip("sandbox-exec not available")
	}
	// Find opencode in PATH.
	opencodePath, err := exec.LookPath("opencode")
	if err != nil || opencodePath == "" {
		t.Skip("opencode not in PATH — skipping opencode SIGABRT test")
	}
	m, stagingHome := newIntegrationManager(t)
	profilePath := writeProfileForIntegration(t, m)

	_, code := runUnderSandbox(t, profilePath, baseEnv(stagingHome), opencodePath, "--help")
	// SIGABRT = signal 6, which becomes exit code 134 on Darwin (128+6).
	const sigabrtExit = 134
	if code == sigabrtExit {
		t.Errorf("opencode --help: exited with SIGABRT (exit code %d) under v3 profile — the dyld fix is not working", code)
	}
}

// TestSandboxExecIntegration_NixBashEchoHi verifies that a Nix-built bash
// exits 0 and prints "hi" under the v3 profile (P9 in F.1 §3.1).
func TestSandboxExecIntegration_NixBashEchoHi(t *testing.T) {
	if !sandboxExecAvailable() {
		t.Skip("sandbox-exec not available")
	}
	// Find bash via PATH — on a Nix host this will resolve to a Nix store path.
	bashPath, err := exec.LookPath("bash")
	if err != nil {
		t.Skip("bash not in PATH")
	}
	// Only run this test if bash is from the Nix store.
	if !strings.HasPrefix(bashPath, "/nix/store/") {
		t.Skipf("bash at %q is not Nix-built — skipping Nix bash test", bashPath)
	}
	m, stagingHome := newIntegrationManager(t)
	profilePath := writeProfileForIntegration(t, m)

	out, code := runUnderSandbox(t, profilePath, baseEnv(stagingHome), bashPath, "-c", "echo hi")
	if code != 0 {
		t.Errorf("Nix bash -c 'echo hi': want exit 0, got %d\noutput: %s", code, out)
	}
	if !strings.Contains(out, "hi") {
		t.Errorf("Nix bash -c 'echo hi': expected 'hi' in output; got: %q", out)
	}
}

// ── Negative cases ────────────────────────────────────────────────────────────

// TestSandboxExecIntegration_SSHKeyDenied verifies that an SSH private key in
// the host home directory is NOT readable from inside the sandbox (N1 in
// F.1 §3.2). Uses a real (or dummy) key file.
func TestSandboxExecIntegration_SSHKeyDenied(t *testing.T) {
	if !sandboxExecAvailable() {
		t.Skip("sandbox-exec not available")
	}
	realHome, err := os.UserHomeDir()
	if err != nil {
		t.Skip("cannot determine home directory")
	}

	// Prefer a real key if it exists; otherwise create a dummy file in a
	// temp location that is NOT the staging home (so it is denied).
	sshKeyPath := filepath.Join(realHome, ".ssh", "id_ed25519")
	if _, err := os.Stat(sshKeyPath); err != nil {
		// Create a dummy key file outside the staging HOME.
		tmpKey := filepath.Join(t.TempDir(), "dummy_key")
		if err := os.WriteFile(tmpKey, []byte("dummy ssh key"), 0o600); err != nil {
			t.Fatalf("create dummy key: %v", err)
		}
		sshKeyPath = tmpKey
	}

	m, stagingHome := newIntegrationManager(t)
	env := baseEnv(stagingHome)
	// Set HOME to the real home so the deny rule for ~/.aws is exercised with
	// the real path; the staging home is a separate temp dir.
	for i, kv := range env {
		if strings.HasPrefix(kv, "HOME=") {
			env[i] = "HOME=" + realHome
		}
	}
	// Re-generate profile with the real home so the deny covers the right path.
	realM := newSandboxExecManager(Config{
		SessionName: "integration-test@main",
		Worktree:    m.cfg.Worktree,
		InstanceID:  "integration-test",
	})
	realProfilePath := writeProfileForIntegration(t, realM)

	out, code := runUnderSandbox(t, realProfilePath, env, "/bin/cat", sshKeyPath)
	if code == 0 {
		t.Errorf("cat SSH key: expected non-zero exit (denied), got exit 0\noutput: %s", out)
	}
	if !strings.Contains(out, "Operation not permitted") && !strings.Contains(out, "Permission denied") {
		t.Errorf("cat SSH key: expected 'Operation not permitted' in output; got: %q", out)
	}
}

// TestSandboxExecIntegration_AWSCredentialsDenied verifies that the host
// ~/.aws/credentials is NOT readable from inside the sandbox (N2 in F.1 §3.2).
func TestSandboxExecIntegration_AWSCredentialsDenied(t *testing.T) {
	if !sandboxExecAvailable() {
		t.Skip("sandbox-exec not available")
	}
	realHome, err := os.UserHomeDir()
	if err != nil {
		t.Skip("cannot determine home directory")
	}

	awsCredPath := filepath.Join(realHome, ".aws", "credentials")
	if _, err := os.Stat(awsCredPath); err != nil {
		// Create a dummy credentials file so we have something to try to read.
		awsDir := filepath.Join(t.TempDir(), ".aws")
		if err := os.MkdirAll(awsDir, 0o755); err != nil {
			t.Fatalf("create dummy .aws dir: %v", err)
		}
		awsCredPath = filepath.Join(awsDir, "credentials")
		if err := os.WriteFile(awsCredPath, []byte("[default]\naws_access_key_id=DUMMY"), 0o600); err != nil {
			t.Fatalf("create dummy credentials: %v", err)
		}
		// Use a manager that denies this specific path.
		m := newSandboxExecManager(Config{
			SessionName: "integration-test@main",
			Worktree:    t.TempDir(),
			InstanceID:  "integration-test",
		})
		// Override the home to point at our temp dir's parent so the deny covers awsDir.
		t.Setenv("HOME", filepath.Dir(awsDir))
		profilePath := writeProfileForIntegration(t, m)
		stagingHome := filepath.Join(t.TempDir(), "staging-home")
		if err := os.MkdirAll(stagingHome, 0o755); err != nil {
			t.Fatalf("mkdir staging home: %v", err)
		}
		env := baseEnv(stagingHome)
		out, code := runUnderSandbox(t, profilePath, env, "/bin/cat", awsCredPath)
		if code == 0 {
			t.Errorf("cat AWS credentials (dummy): expected non-zero exit, got 0\noutput: %s", out)
		}
		return
	}

	// Real ~/.aws/credentials exists — use the real home in the manager.
	m, stagingHome := newIntegrationManager(t)
	env := baseEnv(stagingHome)
	// Pass the real HOME so the deny rule is generated for ~/.aws.
	for i, kv := range env {
		if strings.HasPrefix(kv, "HOME=") {
			env[i] = "HOME=" + realHome
		}
	}
	realM := newSandboxExecManager(Config{
		SessionName: "integration-test@main",
		Worktree:    m.cfg.Worktree,
		InstanceID:  "integration-test",
	})
	realProfilePath := writeProfileForIntegration(t, realM)

	out, code := runUnderSandbox(t, realProfilePath, env, "/bin/cat", awsCredPath)
	if code == 0 {
		t.Errorf("cat ~/.aws/credentials: expected non-zero exit (denied), got exit 0\noutput: %s", out)
	}
	if !strings.Contains(out, "Operation not permitted") && !strings.Contains(out, "Permission denied") {
		t.Errorf("cat ~/.aws/credentials: expected 'Operation not permitted' in output; got: %q", out)
	}
}

// TestSandboxExecIntegration_HomeCodeDirectoryDenied verifies that the host
// ~/code directory is NOT accessible from inside the sandbox (N3 in F.1 §3.2).
func TestSandboxExecIntegration_HomeCodeDirectoryDenied(t *testing.T) {
	if !sandboxExecAvailable() {
		t.Skip("sandbox-exec not available")
	}
	realHome, err := os.UserHomeDir()
	if err != nil {
		t.Skip("cannot determine home directory")
	}
	codeDir := filepath.Join(realHome, "code")
	if _, err := os.Stat(codeDir); err != nil {
		t.Skipf("~/code does not exist on this host — skipping: %v", err)
	}

	m, stagingHome := newIntegrationManager(t)
	profilePath := writeProfileForIntegration(t, m)
	env := baseEnv(stagingHome)

	// find ~/code -name '.env' — should produce no results (directory is inaccessible).
	// Note: find exits 0 even when the root path is denied (operation not permitted
	// on the root argument). We just assert no .env files were found.
	out, _ := runUnderSandbox(t, profilePath, env, "/usr/bin/find", codeDir, "-name", ".env")
	// The output should be empty or contain only the "Operation not permitted" error.
	// We assert that no actual .env file paths appear in the output.
	lines := strings.Split(strings.TrimSpace(out), "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		if strings.HasSuffix(line, ".env") {
			t.Errorf("find ~/code -name .env returned .env file %q — host source tree should be inaccessible", line)
		}
	}
}

