// TestSandboxExecIntegration_DocumentsDenied verifies that a file under
// ~/Documents is NOT readable from inside the sandbox (N5 in F.1 §3.2).
func TestSandboxExecIntegration_DocumentsDenied(t *testing.T) {
	if !sandboxExecAvailable() {
		t.Skip("sandbox-exec not available")
	}
	realHome, err := os.UserHomeDir()
	if err != nil {
		t.Skip("cannot determine home directory")
	}
	// Create a sentinel file in a temp dir that we treat as the Documents test.
	// We don't need the file to really be in ~/Documents — any host-home path
	// that isn't the staging home or worktree should be denied.
	// Use ~/Documents if it exists; otherwise create a temp file in the real home.
	docsDir := filepath.Join(realHome, "Documents")
	var testFilePath string
	if _, err := os.Stat(docsDir); err == nil {
		// Create a file inside Documents for the test.
		testFilePath = filepath.Join(docsDir, "sandbox-exec-test-sentinel.txt")
		if wErr := os.WriteFile(testFilePath, []byte("sentinel"), 0o644); wErr != nil {
			// Can't write to Documents — use a different approach.
			testFilePath = ""
		} else {
			defer os.Remove(testFilePath)
		}
	}
	if testFilePath == "" {
		// Fall back: create a file directly in the real home (not staging, not worktree).
		testFilePath = filepath.Join(realHome, ".sandbox-exec-test-sentinel.txt")
		if wErr := os.WriteFile(testFilePath, []byte("sentinel"), 0o644); wErr != nil {
			t.Skipf("cannot create test sentinel file in home: %v", wErr)
		}
		defer os.Remove(testFilePath)
	}

	m, stagingHome := newIntegrationManager(t)
	profilePath := writeProfileForIntegration(t, m)
	env := baseEnv(stagingHome)

	out, code := runUnderSandbox(t, profilePath, env, "/bin/cat", testFilePath)
	if code == 0 {
		t.Errorf("cat %s: expected non-zero exit (denied), got exit 0\noutput: %s", testFilePath, out)
	}
	if !strings.Contains(out, "Operation not permitted") && !strings.Contains(out, "Permission denied") {
		t.Errorf("cat %s: expected 'Operation not permitted' in output; got: %q", testFilePath, out)
	}
}
